describe('User Authentication - Remember Me Functionality', () => {
    beforeEach(() => {
        cy.visit('/login');
    });

    it('should log in the user and remember them when "Remember Me" is checked', () => {
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="password"]').type('password123');
        cy.get('input[name="rememberMe"]').check();
        cy.get('button[type="submit"]').click();

        // Verify that the user is redirected to the dashboard
        cy.url().should('include', '/dashboard');

        // Close the browser and reopen to check if the user is still logged in
        cy.reload();
        cy.visit('/login');
        cy.url().should('not.include', '/login');
    });

    it('should log in the user but not remember them when "Remember Me" is not checked', () => {
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="password"]').type('password123');
        cy.get('input[name="rememberMe"]').uncheck();
        cy.get('button[type="submit"]').click();

        // Verify that the user is redirected to the dashboard
        cy.url().should('include', '/dashboard');

        // Close the browser and reopen to check if the user is logged out
        cy.reload();
        cy.visit('/login');
        cy.url().should('include', '/login');
    });
});
